  const SETTINGS_ID = "sakalux-oco-settings";
  const STYLE_ID = "sakalux-oco-style";
  const OC_DISMISS_KEY = "sakalux_oco_oc_dismissed_until";
  const ITM_DISMISS_KEY = "sakalux_oco_itm_dismissed_until";
  const HUD_POS_KEY = "sakalux_oco_hud_pos";
  const SETTINGS_KEY = "sakalux_oco_settings";
  const LS_SCANS_KEY = "sakalux_oc_role_scans_v1";
  const LS_NOT_IN_OC_KEY = "sakalux_not_in_oc_v1";
  const OC_INTEL_KEY = "sakalux_oco_member_intelligence_v1";
  const OC_OUTSIDE_KEY = "sakalux_oco_outside_since_v1";
  const OC_API_CACHE_KEY = "sakalux_oco_api_cache_v1";
  const OC_API_CACHE_MS = 10 * 60 * 1000;
  const OC_API_PAGE_LIMIT = 100;
