  function buildItemUsageTitle(itemId, lead) {
    const itemName = OC_ITEM_NAMES[String(itemId)] || `Item #${itemId}`;
    const lines = itemUsageLines(itemId);
    const parts = [];
    if (lead) parts.push(lead);
    if (lines.length) {
      parts.push(`${itemName} is used in:\n${lines.map(line => `• ${line}`).join("\n")}`);
    } else {
      parts.push(`${itemName} is included as an OC utility item, but no OC role usage has been mapped yet.`);
    }
    return parts.join("\n\n");
  }
