    if (recruitingBtn) {
      recruitingBtn.classList.toggle("sakalux-oco-stage-scanned", !!sessionScanState.Recruiting);
      recruitingBtn.title = sessionScanState.Recruiting
        ? "Recruiting - Scan Complete"
        : "Recruiting - Scan Required";
    }
    if (planningBtn) {
      planningBtn.classList.toggle("sakalux-oco-stage-scanned", !!sessionScanState.Planning);
      planningBtn.title = sessionScanState.Planning
        ? "Planning - Scan Complete"
        : "Planning - Scan Required";
    }
