    removeSettings();
    removeHud();
    closeOcIntelTooltip();
    document.getElementById(STYLE_ID)?.remove();
    document.getElementById("sakalux-oco-tab-gear")?.remove();
    document.querySelectorAll(".sakalux-oco-btn-wrap").forEach(el => el.remove());
    document.getElementById("sakalux-oco-intel-panel")?.remove();
