  function addWeightRow(roleRoot, weight, isTopWeight, maxWeight, successValue, priority) {
    const slotBody = q('[class*="slotBody"]', roleRoot);
    if (!slotBody) return;
    let row = q(":scope > .sakalux-oc-weight-row", roleRoot);
    const successTier = getSuccessTier(successValue);
    const weightTier = getWeightTier(weight);
    const suitability = getSuitabilityState(successValue, priority);
    if (!row) {
      row = document.createElement("div");
      row.className = "sakalux-oc-weight-row";
      row.innerHTML = `
        <div class="sakalux-oc-weight-topline">
          <div class="sakalux-oc-weight-left">
            <span class="sakalux-oc-weight-star">★</span>
            <span class="sakalux-oc-weight-label">Weight</span>
          </div>
          <span class="sakalux-oc-weight-value"></span>
        </div>
        <div class="sakalux-oc-weight-bar">
          <div class="sakalux-oc-weight-fill"></div>
        </div>
        <div class="sakalux-oc-suitability-line"></div>
      `;
      slotBody.insertAdjacentElement("afterend", row);
    }
    row.classList.remove(
      "sakalux-success-low",
      "sakalux-success-mid",
      "sakalux-success-high",
      "sakalux-weight-low",
      "sakalux-weight-mid",
      "sakalux-weight-high",
      "sakalux-suitable",
      "sakalux-maybe-suitable",
      "sakalux-not-suitable",
      "sakalux-priority-low",
      "sakalux-priority-normal",
      "sakalux-priority-high",
      "sakalux-priority-critical"
    );
    row.classList.add(`sakalux-success-${successTier.key}`);
    row.classList.add(`sakalux-weight-${weightTier}`);
    row.classList.add(`sakalux-${suitability.key}`);
    row.classList.add(`sakalux-priority-${priority.key}`);
    row.classList.toggle("sakalux-oc-weight-top", !!isTopWeight);
    roleRoot.classList.toggle("sakalux-oc-critical-role", !!isTopWeight);
    const valueEl = q(".sakalux-oc-weight-value", row);
    const fillEl = q(".sakalux-oc-weight-fill", row);
    const suitabilityEl = q(".sakalux-oc-suitability-line", row);
    if (valueEl) {
      valueEl.textContent = `${weight.toFixed(1)}%`;
      valueEl.title = `Required pass rate: ${suitability.requiredPass.toFixed(1)}%`;
    }
    if (suitabilityEl) {
      suitabilityEl.textContent = suitability.label;
      suitabilityEl.title = `Required: ${suitability.requiredPass.toFixed(1)}%`;
    }
    if (fillEl) {
      const relativeWidth = maxWeight > 0 ? (weight / maxWeight) * 100 : 0;
      fillEl.style.width = `${Math.max(0, Math.min(100, relativeWidth))}%`;
    }
  }
  function getPredictedTier(value) {
    if (value <= 49) return "low";
    if (value <= 64) return "mid";
    return "high";
  }
  function getPredictionStatus(predicted, worstCriticalGap, weakCriticalCount, weakHighCount) {
    if (weakCriticalCount > 0) {
      return "Critical Role Weak";
    }
    if (worstCriticalGap >= 15 || weakHighCount >= 2) {
      return "High-Risk Assignment";
    }
    if (predicted >= 75 && weakHighCount === 0) {
      return "Balanced Team";
    }
    if (predicted >= 65) {
      return "Moderate Risk";
    }
    return "Needs Attention";
  }
  function updatePredictedSuccess(ocRoot, roleItems) {
    if (!roleItems || !roleItems.length) return;
    let weightedTotal = 0;
    let weightTotal = 0;
    let penaltyTotal = 0;
    let worstCriticalGap = 0;
    let weakCriticalCount = 0;
    let weakHighCount = 0;
    const highestWeight = Math.max(...roleItems.map((item) => item.weight));
    const averageWeight = roleItems.length > 0 ? 100 / roleItems.length : 0;
    roleItems.forEach(({ weight, successValue }) => {
      if (!Number.isFinite(weight) || !Number.isFinite(successValue)) return;
      weightedTotal += weight * successValue;
      weightTotal += weight;
      const priority = getRolePriority(weight, averageWeight, highestWeight);
      const required = priority.required || 0;
      const gap = Math.max(0, required - successValue);
      if (gap > 0 && priority.key === "critical") {
        weakCriticalCount += 1;
        worstCriticalGap = Math.max(worstCriticalGap, gap);
      }
      if (gap > 0 && priority.key === "high") {
        weakHighCount += 1;
      }
      const priorityMultiplier = priority.key === "critical"
        ? 1.45
        : priority.key === "high"
          ? 1.15
          : priority.key === "normal"
            ? 0.70
            : 0.25;
      penaltyTotal += (weight / 100) * gap * priorityMultiplier;
    });
    if (weightTotal <= 0) return;
    const basePredicted = weightedTotal / weightTotal;
    const predicted = Math.max(0, Math.min(100, basePredicted - penaltyTotal));
    const tier = getPredictedTier(predicted);
    const status = getPredictionStatus(predicted, worstCriticalGap, weakCriticalCount, weakHighCount);
    const panel =
      q('[class^="panel___"]', ocRoot) ||
      q('[class*="panel"]', ocRoot);
    if (!panel) return;
    const panelBody =
      q('[class^="panelBody___"]', panel) ||
      q('[class*="panelBody"]', panel);
    if (!panelBody) return;
    let box = q(":scope > .sakalux-oc-predicted-success", panel);
    if (!box) {
      box = document.createElement("div");
      box.className = "sakalux-oc-predicted-success";
      box.innerHTML = `
        <div class="sakalux-oc-predicted-success-top">
          <span class="sakalux-oc-predicted-success-label">Est. Success</span>
          <span class="sakalux-oc-predicted-success-value"></span>
        </div>
        <div class="sakalux-oc-predicted-success-status"></div>
      `;
      panel.insertBefore(box, panelBody);
    }
    box.classList.remove("sakalux-pred-low", "sakalux-pred-mid", "sakalux-pred-high");
    box.classList.add(`sakalux-pred-${tier}`);
    const valueEl = q(".sakalux-oc-predicted-success-value", box);
    if (valueEl) {
      valueEl.textContent = `${predicted.toFixed(1)}%`;
    }
    const statusEl = q(".sakalux-oc-predicted-success-status", box);
    if (statusEl) {
      statusEl.textContent = status;
    }
  }
  function addWeightBoxes(ocRoot) {
    const ocName = getOCName(ocRoot);
    if (!ocName) return;
    const ocWeights = weightData[normalize(ocName)];
    if (!ocWeights) return;
    const roles = findRoleBlocks(ocRoot);
    const roleItems = [];
    roles.forEach((role) => {
      colourSuccessChance(role);
      const roleName = getRoleName(role);
      if (!roleName) return;
      const weight = ocWeights[normalize(roleName)];
      if (!Number.isFinite(weight)) return;
      roleItems.push({
        role,
        weight,
        successValue: getSuccessValue(role),
      });
    });
    if (!roleItems.length) return;
    updatePredictedSuccess(ocRoot, roleItems);
    const highestWeight = Math.max(...roleItems.map((item) => item.weight));
    const averageWeight = roleItems.length > 0 ? 100 / roleItems.length : 0;
    roleItems.forEach(({ role, weight, successValue }) => {
      const priority = getRolePriority(weight, averageWeight, highestWeight);
      addWeightRow(role, weight, weight === highestWeight, highestWeight, successValue, priority);
    });
  }
  function scanPage() {
    if (!moduleActive) return;
    injectStyles();
    addSettingsPanel();
    const roots = findOCRoots();
    if (!roots.length) return;
    roots.forEach(addWeightBoxes);
  }
  function queueScan() {
    if (!moduleActive) return;
    clearTimeout(scanTimer);
    scanTimer = setTimeout(scanPage, 180);
  }
  function startObserver() {
    if (!moduleActive || observer) return;
    observer = new MutationObserver(queueScan);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });
  }
  function isOcIntelligencePage() {
    const url = location.href.toLowerCase();
    return (
      url.includes("factions.php") ||
      url.includes("organizedcrimes.php")
    );
  }
  function startRenderWatchdog() {
    if (renderWatchdog) {
      clearInterval(renderWatchdog);
    }
    renderWatchdog = setInterval(() => {
      if (!moduleActive || !isOcIntelligencePage()) return;
      const roots = findOCRoots();
      if (!roots.length) return;
      const hasRenderedWeights = roots.some(root =>
        root.querySelector(".sakalux-oc-weight-row")
      );
      if (!hasRenderedWeights) {
        if (!isWeightDataset(weightData)) {
          loadWeights(true);
        }
        scanPage();
      }
    }, 1200);
  }
  function init() {
    if (moduleActive) return;
    moduleActive = true;
    const start = () => {
      if (!moduleActive) return;
      injectStyles();
      startObserver();
      loadWeights();
      queueScan();
      startRenderWatchdog();
    };
    if (document.body) {
      start();
    } else {
      document.addEventListener(
        "DOMContentLoaded",
        start,
        { once: true }
      );
    }
  }
  function destroy() {
    moduleActive = false;
    clearTimeout(scanTimer);
    scanTimer = null;
    clearWeightRetries();
    if (renderWatchdog) {
      clearInterval(renderWatchdog);
      renderWatchdog = null;
    }
    observer?.disconnect();
    observer = null;
    document.getElementById(STYLE_ID)?.remove();
    document.querySelectorAll(".sakalux-oc-weight-row")
      .forEach(element => element.remove());
    document.querySelectorAll(".sakalux-oc-predicted-success")
      .forEach(element => element.remove());
    document.querySelectorAll(".sakalux-oc-settings-wrap")
      .forEach(element => element.remove());
    document.querySelectorAll(
      ".sakalux-oc-critical-role,.sakalux-oc-success-high,.sakalux-oc-success-mid,.sakalux-oc-success-low"
    ).forEach(element => {
      element.classList.remove(
        "sakalux-oc-critical-role",
        "sakalux-oc-success-high",
        "sakalux-oc-success-mid",
        "sakalux-oc-success-low"
      );
    });
    document.querySelectorAll(".sakalux-oc-difficulty-host")
      .forEach(element => {
        element.classList.remove("sakalux-oc-difficulty-host");
      });
  }
  return {
    init,
    destroy,
    onRouteChange: queueScan
  };
