    function findPeopleTabBar() {
        const nativeButtons = [
            ...document.querySelectorAll('button[role="tab"][title]')
        ];
        const friendsButton = nativeButtons.find(button =>
            /^friends list$/i.test(
                normaliseText(button.getAttribute("title"))
            )
        );
        const factionButton = nativeButtons.find(button =>
            /^faction list$/i.test(
                normaliseText(button.getAttribute("title"))
            )
        );
        const blockedButton = nativeButtons.find(button =>
            /^blocked list$/i.test(
                normaliseText(button.getAttribute("title"))
            )
        );
        if (!friendsButton || !factionButton || !blockedButton) {
            return null;
        }
        const tabBar = friendsButton.parentElement;
        if (
            !tabBar ||
            factionButton.parentElement !== tabBar ||
            blockedButton.parentElement !== tabBar
        ) {
            return null;
        }
        return tabBar;
    }
    function getNativeTabTemplate(tabBar) {
        return (
            [...tabBar.querySelectorAll(':scope > button[role="tab"]')].find(
                button => /friends list/i.test(button.title || "")
            ) ||
            tabBar.querySelector(':scope > button[role="tab"]')
        );
    }
    function getSelectedClass(tabBar) {
        const selected = [...tabBar.querySelectorAll(':scope > button[role="tab"]')]
            .find(button =>
                [...button.classList].some(className =>
                    className.startsWith("selected")
                )
            );
        return selected
            ? [...selected.classList].find(className =>
                className.startsWith("selected")
            )
            : "";
    }
    function createPeopleDivider(tabBar) {
        const existing = tabBar.querySelector(':scope > div[class*="divider"]');
        if (existing) {
            return existing.cloneNode(true);
        }
        const divider = document.createElement("div");
        divider.style.width = "1px";
        divider.style.height = "22px";
        divider.style.background = "rgba(255,255,255,.12)";
        return divider;
    }
