    function ensurePeoplePanelTabs() {
        if (!moduleActive) return;
        const tabBar = findPeopleTabBar();
        if (!tabBar) return;
        const existingTargets = document.getElementById(
            PEOPLE_PANEL_IDS.targetsTab
        );
        const existingEnemies = document.getElementById(
            PEOPLE_PANEL_IDS.enemiesTab
        );
        if (
            existingTargets?.isConnected &&
            existingEnemies?.isConnected &&
            existingTargets.parentElement === tabBar &&
            existingEnemies.parentElement === tabBar
        ) {
            return;
        }
        existingTargets?.remove();
        existingEnemies?.remove();
        const template = getNativeTabTemplate(tabBar);
        const targetsButton = createPeopleTab("targets", template);
        const enemiesButton = createPeopleTab("enemies", template);
        tabBar.appendChild(createPeopleDivider(tabBar));
        tabBar.appendChild(targetsButton);
        tabBar.appendChild(createPeopleDivider(tabBar));
        tabBar.appendChild(enemiesButton);
        [...tabBar.querySelectorAll(':scope > button[role="tab"]')]
            .filter(button =>
                button.id !== PEOPLE_PANEL_IDS.targetsTab &&
                button.id !== PEOPLE_PANEL_IDS.enemiesTab
            )
            .forEach(button => {
                if (button.dataset.sakaluxListRestoreBound === "true") {
                    return;
                }
                button.dataset.sakaluxListRestoreBound = "true";
                button.addEventListener("click", () => {
                    restoreNativePeoplePanel();
                });
            });
        if (activePeopleListType) {
            activatePeopleListTab(activePeopleListType);
        }
    }
    function findPeopleContentHost(tabBar) {
        if (!tabBar) return null;
        const panel = tabBar.closest("#people_panel");
        if (!panel) return null;
        return (
            [...panel.children].find(child =>
                child !== tabBar &&
                [...child.classList].some(className =>
                    className.startsWith("content")
                )
            ) ||
            tabBar.nextElementSibling ||
            null
        );
    }
    function hideNativePeopleContent(host) {
        [...host.children].forEach(child => {
            if (child.id === PEOPLE_PANEL_IDS.customPanel) return;
            if (!child.hasAttribute("data-sakalux-people-original-display")) {
                child.setAttribute(
                    "data-sakalux-people-original-display",
                    child.style.display || ""
                );
            }
            child.style.setProperty("display", "none", "important");
        });
    }
    function restoreNativePeoplePanel() {
        activePeopleListType = null;
        const customPanel = document.getElementById(
            PEOPLE_PANEL_IDS.customPanel
        );
        const host = customPanel?.parentElement;
        if (host) {
            [...host.children].forEach(child => {
                if (!child.hasAttribute("data-sakalux-people-original-display")) {
                    return;
                }
                const previous = child.getAttribute(
                    "data-sakalux-people-original-display"
                );
                child.style.removeProperty("display");
                if (previous) {
                    child.style.display = previous;
                }
                child.removeAttribute(
                    "data-sakalux-people-original-display"
                );
            });
        }
        customPanel?.remove();
        const peoplePanel = document.getElementById("people_panel");
        const heading = peoplePanel?.querySelector(
            ':scope > button:first-child span'
        );
        if (heading?.dataset.sakaluxOriginalHeading) {
            heading.textContent =
                heading.dataset.sakaluxOriginalHeading;
        }
        document
            .querySelectorAll(
                `#${PEOPLE_PANEL_IDS.targetsTab}, #${PEOPLE_PANEL_IDS.enemiesTab}`
            )
            .forEach(button => {
                [...button.classList]
                    .filter(className => className.startsWith("selected"))
                    .forEach(className => button.classList.remove(className));
                button.setAttribute("aria-selected", "false");
            });
        requestAnimationFrame(() => {
            for (const type of [
                "targets",
                "enemies"
            ]) {
                if (
                    !pendingPeopleTabAlerts[type]
                ) {
                    continue;
                }
                const id =
                    type === "targets"
                        ? PEOPLE_PANEL_IDS.targetsTab
                        : PEOPLE_PANEL_IDS.enemiesTab;
                if (
                    document.getElementById(id)
                ) {
                    flashPeopleListTab(type);
                }
            }
        });
    }
    function activatePeopleListTab(type) {
        if (!LIST_TYPES[type]) return;
        const tabBar = findPeopleTabBar();
        if (!tabBar) return;
        const host = findPeopleContentHost(tabBar);
        if (!host) return;
        cacheNativePeopleTemplate();
        activePeopleListType = type;
        const selectedClass = getSelectedClass(tabBar);
        [...tabBar.querySelectorAll(':scope > button[role="tab"]')]
            .forEach(button => {
                [...button.classList]
                    .filter(className => className.startsWith("selected"))
                    .forEach(className => button.classList.remove(className));
                button.setAttribute("aria-selected", "false");
            });
        const activeButton = document.getElementById(
            type === "targets"
                ? PEOPLE_PANEL_IDS.targetsTab
                : PEOPLE_PANEL_IDS.enemiesTab
        );
        if (selectedClass && activeButton) {
            activeButton.classList.add(selectedClass);
        }
        activeButton?.setAttribute("aria-selected", "true");
        const peoplePanel = tabBar.closest("#people_panel");
        const heading = peoplePanel?.querySelector(
            ':scope > button:first-child span'
        );
        if (heading) {
            if (!heading.dataset.sakaluxOriginalHeading) {
                heading.dataset.sakaluxOriginalHeading =
                    heading.textContent || "";
            }
            heading.textContent = `${LIST_TYPES[type].label} list`;
        }
        hideNativePeopleContent(host);
        renderPeopleListPanel(type, host);
    }
    function cacheNativePeopleTemplate() {
        if (nativePeopleTemplateCache) {
            return nativePeopleTemplateCache;
        }
        const peoplePanel = document.getElementById("people_panel");
        if (!peoplePanel) return null;
        const content = peoplePanel.querySelector(
            ':scope > div[class*="content"]'
        );
        if (!content) return null;
        const searchInput = content.querySelector(
            'input[placeholder="Search by player name"]'
        );
        const searchRoot =
            searchInput?.closest('div[class*="root"]') ||
            searchInput?.parentElement?.parentElement ||
            null;
        const list =
            content.querySelector("#friend-user-list") ||
            content.querySelector("#faction-user-list") ||
            content.querySelector("#recent-user-list") ||
            content.querySelector("#blocked-user-list") ||
            [...content.querySelectorAll('[id$="-user-list"]')].find(
                element => !element.id.startsWith("sakalux-")
            ) ||
            null;
        const listInner = list?.firstElementChild || null;
        const sampleRow =
            listInner?.querySelector(':scope > div') ||
            null;
        if (!searchRoot || !list || !sampleRow) {
            return null;
        }
        const activityClasses = {
            Online: "",
            Idle: "",
            Offline: ""
        };
        [
            ...content.querySelectorAll(
                'a[data-label="avatar"]'
            )
        ].forEach(avatarLink => {
            for (const state of Object.keys(activityClasses)) {
                const match = [...avatarLink.classList].find(
                    className =>
                        className.toLowerCase().startsWith(
                            state.toLowerCase()
                        )
                );
                if (match && !activityClasses[state]) {
                    activityClasses[state] = match;
                }
            }
        });
        nativePeopleTemplateCache = {
            contentClassName: content.className,
            searchRoot: searchRoot.cloneNode(true),
            listClassName: list.className,
            sampleRow: sampleRow.cloneNode(true),
            activityClasses
        };
        return nativePeopleTemplateCache;
    }
    function getNativePeopleTemplate() {
        return (
            nativePeopleTemplateCache ||
            cacheNativePeopleTemplate()
        );
    }
    function findNativeActivityClass(activity) {
        const normalised = normaliseState(activity);
        const cached =
            nativePeopleTemplateCache
                ?.activityClasses
                ?.[normalised];
        if (cached) {
            return cached;
        }
        const panel = document.getElementById("people_panel");
        const links = [
            ...(panel?.querySelectorAll(
                'a[data-label="avatar"]'
            ) || [])
        ];
        const prefix = String(normalised || "")
            .toLowerCase();
        for (const link of links) {
            const className = [...link.classList].find(name =>
                name.toLowerCase().startsWith(prefix)
            );
            if (className) return className;
        }
        return {
            Online: "online___SzVd7",
            Idle: "idle___BYvMB",
            Offline: "offline___ZJSbH"
        }[normalised] || "";
    }
    function removeNativeActivityClasses(element) {
        [...element.classList]
            .filter(className =>
                /^(online|idle|offline)___/i.test(className)
            )
            .forEach(className =>
                element.classList.remove(className)
            );
    }
    function makeUniqueSvgIds(root, suffix) {
        root.querySelectorAll("svg").forEach((svg, svgIndex) => {
            const oldSvgId = svg.id;
            const newSvgId =
                `sakalux_${suffix}_svg_${svgIndex}`;
            if (oldSvgId) {
                svg.id = newSvgId;
            }
            svg.querySelectorAll("[id]").forEach((node, nodeIndex) => {
                const oldId = node.id;
                const newId =
                    `sakalux_${suffix}_${svgIndex}_${nodeIndex}`;
                node.id = newId;
                svg.querySelectorAll("*").forEach(descendant => {
                    for (const attribute of [
                        "fill",
                        "stroke",
                        "filter",
                        "clip-path",
                        "mask"
                    ]) {
                        const value =
                            descendant.getAttribute(attribute);
                        if (
                            value &&
                            value.includes(`#${oldId}`)
                        ) {
                            descendant.setAttribute(
                                attribute,
                                value.replace(
                                    `#${oldId}`,
                                    `#${newId}`
                                )
                            );
                        }
                    }
                });
            });
        });
    }
