    function loadJSON(key, fallback) {
      try {
        const parsed = JSON.parse(localStorage.getItem(key));
        return parsed ?? fallback;
      } catch {
        return fallback;
      }
    }
    function saveJSON(key, value) {
      try {
        localStorage.setItem(key, JSON.stringify(value));
      } catch (error) {
        console.warn("[SakaLuX Member Travel Map] Storage error", error);
      }
    }
    function moduleSettings() {
      context.settings.moduleSettings ||= {};
      const saved = context.settings.moduleSettings.factionMemberView || {};
      const merged = {
        ...DEFAULT_MODULE_SETTINGS,
        ...saved,
        inactivityLevels: Array.isArray(saved.inactivityLevels)
          ? saved.inactivityLevels
          : DEFAULT_MODULE_SETTINGS.inactivityLevels.map(item => ({ ...item })),
        tagDefinitions: Array.isArray(saved.tagDefinitions)
          ? saved.tagDefinitions
          : DEFAULT_MODULE_SETTINGS.tagDefinitions.map(item => ({ ...item })),
        autoInactiveWarning: {
          ...DEFAULT_MODULE_SETTINGS.autoInactiveWarning,
          ...(saved.autoInactiveWarning || {})
        },
        customProfileFields: Array.isArray(saved.customProfileFields)
          ? saved.customProfileFields
          : [...DEFAULT_MODULE_SETTINGS.customProfileFields]
      };
      context.settings.moduleSettings.factionMemberView = merged;
      return merged;
    }
    function persistModuleSettings(next) {
      context.settings.moduleSettings ||= {};
      context.settings.moduleSettings.factionMemberView = next;
      saveSettings();
    }
    function clean(value) {
      return String(value ?? "").replace(/\s+/g, " ").trim();
    }
    function esc(value) {
      return escapeHtml(value);
    }
    function safeColor(value, fallback = "#607d8b") {
      const input = String(value || "").trim();
      return /^#[0-9a-f]{6}$/i.test(input) ? input : fallback;
    }
    function sharedApiKey() {
      return String(context.settings.api?.key || "").trim();
    }
    function requestJSON(url) {
      return new Promise((resolve, reject) => {
        const request = typeof GM_xmlhttpRequest === "function"
          ? GM_xmlhttpRequest
          : (typeof GM?.xmlHttpRequest === "function" ? GM.xmlHttpRequest : null);
        if (!request) {
          reject(new Error("Torn API request helper is unavailable"));
          return;
        }
        request({
          method: "GET",
          url,
          timeout: 30000,
          headers: { Accept: "application/json" },
          onload(response) {
            try {
              const data = JSON.parse(response.responseText || "{}");
              if (data?.error) {
                reject(new Error(data.error.error || "Torn API error"));
                return;
              }
              resolve(data);
            } catch {
              reject(new Error("Invalid response from Torn API"));
            }
          },
          onerror: () => reject(new Error("Unable to contact Torn API")),
          ontimeout: () => reject(new Error("Torn API request timed out"))
        });
      });
    }
    function pageContext() {
      if (location.pathname !== "/factions.php") return null;
      const params = new URLSearchParams(location.search);
      const step = params.get("step");
      const hash = String(location.hash || "").toLowerCase();
      if (
        step === "your" &&
        hash.includes("tab=info") &&
        (!params.has("type") || params.get("type") === "1")
      ) {
        return { type: "own", key: "your:info" };
      }
      if (step === "profile" && params.get("ID")) {
        const factionId = String(params.get("ID"));
        return { type: "profile", factionId, key: `profile:${factionId}` };
      }
      return null;
    }
    function findNativeSection() {
      const direct = document.querySelector(
        ".f-war-list.members-list, div.f-war-list.members-list"
      );
      if (direct) return direct;
      const candidates = [
        '[class*="members-list"]',
        '[class*="membersList"]',
        '[data-faction-members]'
      ];
      for (const selector of candidates) {
        const found = [...document.querySelectorAll(selector)].find(node => {
          if (node.id === APP_ID || node.closest(`#${APP_ID}`)) return false;
          return node.querySelectorAll('a[href*="profiles.php?XID="]').length >= 2;
        });
        if (found) return found;
      }
      return null;
    }
    function scrapeVisibleMembers() {
      const native = findNativeSection();
      if (!native) return [];
      let rows = [...native.querySelectorAll(".table-body > .table-row")];
      if (!rows.length) {
        rows = [...native.querySelectorAll(".table-row")].filter(row =>
          row.querySelector('a[href*="profiles.php?XID="]')
        );
      }
      return rows.map(row => {
        const profileLink = row.querySelector('a[href*="profiles.php?XID="]');
        const href = profileLink?.getAttribute("href") || "";
        const id = Number(href.match(/[?&]XID=(\d+)/i)?.[1] || 0);
        if (!id) return null;
        const name = clean(
          profileLink?.querySelector(".honor-text:last-of-type")?.textContent ||
          profileLink?.querySelector(".honor-text")?.textContent ||
          profileLink?.getAttribute("aria-label")?.replace(/^View profile of\s+/i, "") ||
          profileLink?.textContent ||
          `Player ${id}`
        );
        const onlineWrap = row.querySelector(
          '[aria-label$=" is online"], [aria-label$=" is idle"], [aria-label$=" is offline"]'
        );
        const onlineLabel = onlineWrap?.getAttribute("aria-label") || "";
        const lastActionStatus = / is online$/i.test(onlineLabel)
          ? "Online"
          : / is idle$/i.test(onlineLabel)
            ? "Idle"
            : "Offline";
        const level = Number(clean(
          row.querySelector(".table-cell.lvl:not(.ffscouter-cell)")?.textContent
        ) || 0);
        const position = clean(
          row.querySelector(".table-cell.position .ellipsis")?.getAttribute("title") ||
          row.querySelector(".table-cell.position")?.textContent ||
          "Member"
        );
        const daysCell = row.querySelector(".table-cell.days");
        const days = Number(
          daysCell?.dataset.sakaluxOriginalDays ||
          clean(daysCell?.querySelector(".sakalux-country-days-number")?.textContent) ||
          clean(daysCell?.textContent) ||
          0
        );
        const statusText = clean(
          row.querySelector(".table-cell.status .ellipsis")?.textContent ||
          row.querySelector(".table-cell.status")?.textContent ||
          "Okay"
        );
        const ariaNodes = [...row.querySelectorAll(".table-cell.member-icons [aria-label]")];
        const labels = ariaNodes.map(node => clean(node.getAttribute("aria-label")));
        const companyEl = ariaNodes.find(node =>
          clean(node.getAttribute("aria-label")).startsWith("Company:")
        );
        const jobEl = ariaNodes.find(node =>
          clean(node.getAttribute("aria-label")).startsWith("Job:")
        );
        const marriedEl = ariaNodes.find(node =>
          clean(node.getAttribute("aria-label")).startsWith("Married:")
        );
        const travelLabel = labels.find(label => /^Traveling|^Travelling/i.test(label)) || "";
        const companyLabel = clean(companyEl?.getAttribute("aria-label"));
        const jobLabel = clean(jobEl?.getAttribute("aria-label"));
        const companyClean = companyLabel.replace(/^Company:\s*/i, "");
        const companyMatch = companyClean.match(/^(.+?)\s+of\s+(.+)$/i);
        const companyName = companyMatch?.[2] || jobLabel.replace(/^Job:\s*/i, "") || companyClean;
        const companyPosition = companyMatch?.[1] || "";
        const marriedLabel = clean(marriedEl?.getAttribute("aria-label"));
        const spouse = marriedLabel.replace(/^Married:\s*(?:To\s*)?/i, "").trim();
        return {
          id,
          name,
          level,
          days,
          rank: position,
          lastActionStatus,
          lastActionRelative: lastActionStatus === "Online" ? "Online" : "Unknown",
          lastActionTimestamp: 0,
          statusState: statusText,
          statusDescription: statusText,
          statusDetails: "",
          statusUntil: 0,
          locationCountry: "",
          travelText: travelLabel,
          companyName,
          companyPosition,
          employmentType: companyLabel ? "company" : jobLabel ? "city-job" : "",
          companyHref: companyEl?.getAttribute("href") || companyEl?.closest("a")?.getAttribute("href") || "",
          married: Boolean(marriedLabel),
          spouse,
          spouseHref: marriedEl?.getAttribute("href") || marriedEl?.closest("a")?.getAttribute("href") || ""
        };
      }).filter(Boolean);
    }
    function normaliseApiMembers(payload) {
      const raw = payload?.members || payload?.faction?.members || [];
      const list = Array.isArray(raw)
        ? raw
        : Object.entries(raw).map(([id, value]) => ({ id: Number(id), ...value }));
      return list.map(item => ({
        id: Number(item.id || item.user_id || item.player_id),
        name: item.name || item.player_name || `Player ${item.id}`,
        level: Number(item.level || 0),
        days: Number(item.days_in_faction || item.days || 0),
        rank: item.position || item.position_name || item.role || "Member",
        lastActionStatus: item.last_action?.status || item.lastAction?.status || "",
        lastActionRelative: item.last_action?.relative || item.lastAction?.relative || "",
        lastActionTimestamp: Number(item.last_action?.timestamp || item.lastAction?.timestamp || 0),
        statusState: item.status?.state || item.status_state || "",
        statusDescription: item.status?.description || item.status_description || "",
        statusDetails: item.status?.details || item.status_details || "",
        statusUntil: Number(item.status?.until || item.status_until || 0),
        locationCountry: item.location?.country || item.country || "",
        travelText: item.travel?.destination || item.travel_destination || "",
        companyName: item.company?.name || item.company_name || "",
        companyPosition: item.company?.position || item.job_position || "",
        employmentType: item.company?.id || item.company_id ? "company" : "",
        companyHref: item.company?.id
          ? `/joblist.php#/p=corpinfo&ID=${item.company.id}`
          : item.company_id
            ? `/joblist.php#/p=corpinfo&ID=${item.company_id}`
            : "",
        married: item.married ?? item.is_married ?? null,
        spouse: item.spouse_name || item.married?.spouse_name || "",
        spouseHref: item.spouse_id
          ? `/profiles.php?XID=${item.spouse_id}`
          : item.married?.spouse_id
            ? `/profiles.php?XID=${item.married.spouse_id}`
            : ""
      })).filter(item => item.id && item.name);
    }
    function mergeMembers(apiMembers, scrapedMembers) {
      if (!apiMembers.length) return scrapedMembers;
      const scrapedById = new Map(scrapedMembers.map(member => [member.id, member]));
      return apiMembers.map(member => {
        const scraped = scrapedById.get(member.id) || {};
        return {
          ...scraped,
          ...member,
          rank: member.rank || scraped.rank || "Member",
          companyName: member.companyName || scraped.companyName || "",
          companyPosition: member.companyPosition || scraped.companyPosition || "",
          employmentType: member.employmentType || scraped.employmentType || "",
          companyHref: member.companyHref || scraped.companyHref || "",
          married: member.married ?? scraped.married ?? null,
          spouse: member.spouse || scraped.spouse || "",
          spouseHref: member.spouseHref || scraped.spouseHref || "",
          travelText: member.travelText || scraped.travelText || ""
        };
      });
    }
    async function fetchMembers(force = false, page = pageContext()) {
      const scraped = scrapeVisibleMembers();
      const key = sharedApiKey();
      const factionId = page?.type === "profile" ? String(page.factionId || "") : "";
      const cacheKey = `${CACHE_STORAGE}:${factionId || "own"}`;
      const cached = loadJSON(cacheKey, null);
      if (
        !force && cached?.timestamp &&
        Date.now() - cached.timestamp < CACHE_MS &&
        Array.isArray(cached.members) && cached.members.length
      ) {
        return mergeMembers(cached.members, scraped);
      }
      if (!key) return scraped;
      let lastError = null;

      try {
        const response =
          await getSharedFactionMembersPayload(
            key,
            factionId,
            force
          );

        const members =
          normaliseApiMembers(response);

        if (members.length) {
          saveJSON(
            cacheKey,
            {
              timestamp: Date.now(),
              members
            }
          );
          return mergeMembers(
            members,
            scraped
          );
        }
      } catch (error) {
        lastError = error;
      }

      const legacyEndpoint = factionId
        ? `https://api.torn.com/faction/${encodeURIComponent(factionId)}?selections=basic&key=${encodeURIComponent(key)}`
        : `https://api.torn.com/faction/?selections=basic&key=${encodeURIComponent(key)}`;

      try {
        const response =
          await requestJSON(
            legacyEndpoint
          );
        const members =
          normaliseApiMembers(response);

        if (members.length) {
          saveJSON(
            cacheKey,
            {
              timestamp: Date.now(),
              members
            }
          );
          return mergeMembers(
            members,
            scraped
          );
        }
      } catch (error) {
        lastError = error;
      }

      if (scraped.length) return scraped;
      throw lastError || new Error("No faction members were found");
    }
