    function loadCountryMap() {
        const now = performance.now();
        if (
            countryMapCache &&
            now - countryMapCacheAt < COUNTRY_MAP_CACHE_MS
        ) {
            return countryMapCache;
        }
        try {
            countryMapCache = JSON.parse(
                localStorage.getItem(STORAGE_KEY) || '{}'
            );
        } catch (e) {
            console.error('[SakaLuX Flags]', e);
            countryMapCache = {};
        }
        countryMapCacheAt = now;
        return countryMapCache;
    }
    function saveCountryMap(map) {
        countryMapCache =
            map && typeof map === 'object' ? map : {};
        countryMapCacheAt = performance.now();
        localStorage.setItem(
            STORAGE_KEY,
            JSON.stringify(countryMapCache)
        );
    }
    function clearCountryMap() {
        countryMapCache = {};
        countryMapCacheAt = performance.now();
        localStorage.removeItem(STORAGE_KEY);
    }
    function exportCountryFlags() {
        const map = loadCountryMap();
        const payload = {
            format: "sakalux-country-flags",
            version: 1,
            exportedAt: new Date().toISOString(),
            countries: map
        };
        const blob = new Blob(
            [JSON.stringify(payload, null, 2)],
            { type: "text/plain;charset=utf-8" }
        );
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        const stamp = new Date().toISOString().slice(0, 10);
        anchor.href = url;
        anchor.download = `SakaLuX-Country-Flags-${stamp}.txt`;
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
    function normaliseImportedCountryMap(value) {
        const source =
            value && typeof value === "object" && !Array.isArray(value)
                ? (value.countries && typeof value.countries === "object"
                    ? value.countries
                    : value)
                : null;
        if (!source) {
            throw new Error("No country flag data found.");
        }
        const safe = {};
        for (const [userId, entry] of Object.entries(source)) {
            if (!/^\d+$/.test(String(userId))) continue;
            const code = String(entry?.code || "").trim().toUpperCase();
            const country =
                getCountryByCode(code) ||
                COUNTRIES.find(item =>
                    String(item.name).toLowerCase() ===
                    String(entry?.name || "").trim().toLowerCase()
                );
            if (!country) continue;
            safe[String(userId)] = {
                code: country.code,
                name: country.name
            };
        }
        return safe;
    }
    function importCountryFlagsFile(file) {
        if (!file) return;
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const parsed = JSON.parse(String(reader.result || ""));
                const imported = normaliseImportedCountryMap(parsed);
                const count = Object.keys(imported).length;
                if (!count) {
                    throw new Error("The file did not contain any valid member countries.");
                }
                const current = loadCountryMap();
                const replace = confirm(
                    `Import ${count} saved country flags?\n\n` +
                    "OK = replace the current country flag data.\n" +
                    "Cancel = merge the imported flags with the current data."
                );
                const next = replace
                    ? imported
                    : { ...current, ...imported };
                saveCountryMap(next);
                activeCountryCode = null;
                refreshAllFlags();
                applyCountrySort();
                refreshMapModal();
                alert(`Country flags imported: ${count}`);
            } catch (error) {
                alert(`Country flag import failed:\n${error.message}`);
            }
        };
        reader.onerror = () => {
            alert("Country flag import failed: unable to read the selected file.");
        };
        reader.readAsText(file);
    }
    function getSortState() {
        return currentSortState || "none";
    }
    function setSortState(s) {
        currentSortState = String(s || "none");
    }
    function parseCompactMemberStat(value) {
        const raw = String(value || "")
            .trim()
            .toLowerCase()
            .replace(/,/g, "");
        if (!raw || raw === "-") return 0;

        const compact = raw.match(
            /([0-9]+(?:\.[0-9]+)?)\s*([kmbt])\b/i
        );
        if (compact) {
            const number = Number(compact[1] || 0);
            const multiplier = {
                k: 1e3,
                m: 1e6,
                b: 1e9,
                t: 1e12
            }[compact[2] || ""] || 1;
            return Number.isFinite(number)
                ? number * multiplier
                : 0;
        }

        const plain = raw.match(/([0-9]+(?:\.[0-9]+)?)/);
        if (!plain) return 0;
        const number = Number(plain[1] || 0);
        return Number.isFinite(number) ? number : 0;
    }

    function getRowBspValue(row) {
        const node = row?.querySelector?.(
            ".TDup_ColoredStatsInjectionDiv .iconStats[data-bsp-stats], .iconStats[data-bsp-stats]"
        );
        const raw = Number(node?.dataset?.bspStats || 0);
        if (Number.isFinite(raw) && raw > 0) return raw;
        return parseCompactMemberStat(node?.textContent || "");
    }

    function getRowFfValue(row) {
        const cell = row?.querySelector?.(
            ".table-cell.lvl.ffscouter-cell, .table-cell.ffscouter-cell, .ffscouter-cell"
        );
        return parseCompactMemberStat(cell?.textContent || "");
    }

    function getCountryByCode(code) {
        return COUNTRIES.find(c => c.code === code) || null;
    }
    function getFlagImageUrl(code) {
        if (!code || code.length !== 2) return '';
        return `https://flagcdn.com/32x24/${code.toLowerCase()}.png`;
    }
    function escapeHtml(str) {
        return String(str || '')
            .replaceAll('&', '&amp;')
            .replaceAll('<', '&lt;')
            .replaceAll('>', '&gt;')
            .replaceAll('"', '&quot;')
            .replaceAll("'", '&#039;');
    }
