const TRAIN_GAINS = (() => {
    const out = {};
    for (const [co, roles] of Object.entries(ROLES)) {
        out[co] = {};
        for (const r of roles) {
            const keys = Object.keys(r.req || {});
            const gains = [];
            if (keys[0]) gains.push(`${keys[0]} +50`);
            if (keys[1]) gains.push(`${keys[1]} +25`);
            out[co][r.role] = gains;
        }
    }
    return out;
})();
