const cssVar    = n => getComputedStyle(document.documentElement).getPropertyValue(`--sakalux-${n}`).trim() || THEME[n] || "";
const wait      = ms => new Promise(r => setTimeout(r, ms));
const cleanNum  = v => parseFloat(String(v||"").replace(/,/g,"").replace(/[^0-9.]/g,"")) || 0;
const parseMoney= v => { const n=parseFloat(String(v||"").replace(/[^0-9.\-]/g,"")); return isFinite(n)?n:0; };
const roundWhole= v => { const n=Number(v)||0; return n-Math.floor(n)>=.5?Math.ceil(n):Math.floor(n); };
const fmtMoney  = v => "$"+roundWhole(v).toLocaleString();
const fmtPct    = v => roundWhole(v)+"%";
const cleanText = v => String(v||"").replace(/\s+/g," ").trim();
const normName  = s => cleanText(s).toLowerCase();
const normRole  = s => String(s||"").replace(/^[🥇🥈🥉]\s*/,"").replace(/\s+/g," ").trim().toLowerCase();
const escHtml   = s => String(s).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const pctDiff   = (a,b) => b===0?0:((a-b)/b)*100;
const normTip   = t => String(t||"").replace(/\u00a0/g," ").replace(/[ \t]+/g," ").replace(/\s*\n\s*/g,"\n").trim();
function parseAbbrev(raw) {
    const s=String(raw||"").trim().toLowerCase().replace(/,/g,"");
    const m=s.match(/(-?\d+(?:\.\d+)?)([kmb])?$/i);
    if(!m)return 0;
    const suf=(m[2]||"").toLowerCase();
    return Math.round(parseFloat(m[1])*(suf==="k"?1e3:suf==="m"?1e6:suf==="b"?1e9:1));
}
function parseAgeDays(v) {
    const t=normName(v); let d=0;
    [[/(\d+)\s*year/g,365],[/(\d+)\s*month/g,30],[/(\d+)\s*week/g,7],[/(\d+)\s*day/g,1],[/(\d+)\s*hour/g,1/24]]
        .forEach(([r,m])=>{let x;while((x=r.exec(t))!==null)d+=Number(x[1])*m;});
    return d;
}
const onCompanies = () => location.pathname.includes("/companies.php");
const onJoblist   = () => location.pathname.includes("/joblist.php");
function isPricingTabActive() {
    const t = document.querySelector('li[aria-controls="pricing"]');
    return !!t && (t.classList.contains("ui-tabs-active") || t.classList.contains("ui-state-active") || t.getAttribute("aria-selected")==="true");
}
function isEmployeesView() {
    if (!onCompanies()) return false;
    if (new URL(location.href).searchParams.get("step") !== "your") return false;
    return !!(document.querySelector('a[href*="step=trainemp2"]') || document.querySelector(".effectiveness, .effectiveness.clearfix") || (location.hash||"").includes("option=employees"));
}
