function brVisibleTip(){const cands=[...document.querySelectorAll("body *")].filter(el=>{const s=getComputedStyle(el);if(s.display==="none"||s.visibility==="hidden"||s.opacity==="0")return false;const r=el.getBoundingClientRect();if(!r.width||!r.height)return false;const t=normTip(el.innerText||el.textContent||"");return t&&/working stats\s*:/i.test(t)&&/effectiveness\s*:/i.test(t);});if(!cands.length)return"";cands.sort((a,b)=>normTip(b.innerText||"").length-normTip(a.innerText||"").length);return normTip(cands[0].innerText||cands[0].textContent||"");}
function brFallbackTip(li){const eff=li.querySelector(".effectiveness,.effectiveness.clearfix");if(!eff)return"";const chunks=[];eff.querySelectorAll("[data-title],[title],[aria-label]").forEach(el=>{[el.getAttribute("data-title"),el.getAttribute("title"),el.getAttribute("aria-label")].forEach(v=>{const t=normTip(v||"");if(t)chunks.push(t);});});return normTip(chunks.join("\n"));}
