    m.querySelector("#fpc-exact-apply").addEventListener("click",()=>{const li=m.dataset.employeePointer?document.querySelector(m.dataset.employeePointer):null;if(!li)return;const v=Math.round(parseFloat(document.getElementById("fpc-exact-pay")?.value||"")||0);if(!v)return;const payInput=li.querySelector("input.employee-input-pay")||li.querySelector('.pay input')||li.querySelector('[aria-label="Pay"]');if(!payInput)return;const str=v.toLocaleString();payInput.value=str;payInput.setAttribute("value",str);["input","change","blur"].forEach(ev=>payInput.dispatchEvent(new Event(ev,{bubbles:true})));const btn=m.querySelector("#fpc-exact-apply");if(btn){const orig=btn.textContent;btn.textContent="Applied ✓";setTimeout(()=>btn.textContent=orig,1400);}});
    ["fpc-m","fpc-i","fpc-e","fpc-merits","fpc-merit-rate","fpc-settled","fpc-settled-rate","fpc-dir-ed","fpc-dir-ed-rate","fpc-addiction","fpc-addiction-rate","fpc-inactive","fpc-inactive-rate","fpc-adjustment","fpc-mode","fpc-rate","fpc-current-pay","fpc-base-pay"].forEach(id=>{const el=m.querySelector(`#${id}`);if(el){el.addEventListener("input",recalcPay);el.addEventListener("change",recalcPay);}});
    _PAY_PERSIST_FIELDS.forEach(id=>{const el=m.querySelector(`#${id}`);if(el){el.addEventListener("change",psSave);el.addEventListener("input",psSave);}});
