function openTaxModal(){
    taxSyncFromDOM();
    buildTaxModal();
    const ov=document.getElementById("fc-tax-overlay"),m=document.getElementById("fc-tax-modal");
    if(!ov||!m)return;
    renderTaxModal();
    ov.style.display="block";
    m.style.display="flex";
}
function renderTaxModal(){
    const body=document.getElementById("fc-tax-modal-body");if(!body)return;
    const d=taxLoad();const emps=Object.keys(d.employees||{});
    const periodKey=taxCurrentPeriod(d.defaultFreq||"weekly");
    const periodLbl=taxPeriodLabel(d.defaultFreq||"weekly",periodKey);
    const paidN=emps.filter(n=>{const e=d.employees[n];return!!(e.periods&&e.periods[taxCurrentPeriod(e.freq||d.defaultFreq||"weekly")]);}).length;
    if(!emps.length){
        body.innerHTML=`<div style="padding:var(--sakalux-spaceLg);text-align:center;color:var(--sakalux-textMuted)">No employees yet - visit the Employees tab first to auto-populate, or add manually via Settings.</div>`;
        return;
    }
    const rowsHtml=emps.map(name=>{
        const e=d.employees[name];const freq=e.freq||d.defaultFreq||"weekly";
        const key=taxCurrentPeriod(freq);const paid=!!(e.periods&&e.periods[key]);
        const taxFmt=`$${(e.tax||d.defaultTax||0).toLocaleString()}`;
        const freqLabel=freq==="biweekly"?"Biweekly":freq==="monthly"?"Monthly":"Weekly";
        return`<tr style="background:var(--sakalux-elevated)">
            <td style="padding:9px 12px;border-bottom:1px solid var(--sakalux-border)"><strong style="color:var(--sakalux-text);font-size:13px">${escHtml(name)}</strong></td>
            <td style="padding:9px 12px;border-bottom:1px solid var(--sakalux-border);color:var(--sakalux-textMuted);font-size:11px">${freqLabel}</td>
            <td style="padding:9px 12px;border-bottom:1px solid var(--sakalux-border);color:var(--sakalux-text);font-weight:400">${taxFmt}</td>
            <td style="padding:9px 12px;border-bottom:1px solid var(--sakalux-border)"><span class="fc-tax-pill ${paid?"paid":"unpaid"}" data-tn="${escHtml(name)}" data-tk="${escHtml(key)}">${paid?"✓ Paid":"Unpaid"}</span></td>
        </tr>`;
    }).join("");
    body.innerHTML=`
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:var(--sakalux-spaceMd);flex-wrap:wrap;gap:8px">
            <div style="font-size:13px;font-weight: 400;color:var(--sakalux-text)">Period: ${escHtml(periodLbl)}</div>
            <div style="padding:4px 10px;border-radius:999px;font-size:11px;font-weight: 400;background:var(--sakalux-panel2);border:1px solid var(--sakalux-border);color:var(--sakalux-textSoft)">${paidN} / ${emps.length} paid</div>
        </div>
        <div style="border-radius:var(--sakalux-radiusMd);border:1px solid var(--sakalux-border);overflow:hidden">
            <table style="width:100%;border-collapse:collapse;font-size:12px">
                <thead><tr style="background:var(--sakalux-panel2)">
                    <th style="padding:8px 12px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--sakalux-textMuted)">Employee</th>
                    <th style="padding:8px 12px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--sakalux-textMuted)">Frequency</th>
                    <th style="padding:8px 12px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--sakalux-textMuted)">Tax</th>
                    <th style="padding:8px 12px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.6px;color:var(--sakalux-textMuted)">Status</th>
                </tr></thead>
                <tbody>${rowsHtml}</tbody>
            </table>
        </div>
    `;
    body.querySelectorAll(".fc-tax-pill").forEach(pill=>{
        pill.addEventListener("click",()=>{
            const n=pill.dataset.tn,k=pill.dataset.tk;
            const d=taxLoad();if(!d.employees[n])return;
            if(!d.employees[n].periods)d.employees[n].periods={};
            d.employees[n].periods[k]=!d.employees[n].periods[k];
            taxSave(d);
            const nowPaid=d.employees[n].periods[k];
            pill.className="fc-tax-pill "+(nowPaid?"paid":"unpaid");
            pill.textContent=nowPaid?"✓ Paid":"Unpaid";
            updateTaxBtn();
        });
    });
}
