    function getEffective(item) {
      const multiplier = item.noBonusApplied
        ? 1
        : 1 + getTotalBonusPct() / 100;
      return {
        hospMins:
          item.baseHospMins === null
            ? null
            : Math.round(item.baseHospMins * multiplier),
        lifePct:
          Math.round(item.baseLifePct * multiplier * 10) / 10
      };
    }
    function parseSlash(value) {
      const match = String(value || "").match(
        /(\d[\d,]*)\s*\/\s*(\d[\d,]*)/
      );
      if (!match) return null;
      const first = Number.parseInt(match[1].replace(/,/g, ""), 10);
      const second = Number.parseInt(match[2].replace(/,/g, ""), 10);
      if (
        !Number.isFinite(first) ||
        !Number.isFinite(second) ||
        second <= 0
      ) {
        return null;
      }
      return {
        current: Math.min(first, second),
        max: Math.max(first, second)
      };
    }
    function parseDuration(value) {
      const text = String(value || "");
      let minutes = 0;
      const days = text.match(/(\d+)\s*d(?:ay)?s?/i);
      const hours = text.match(/(\d+)\s*h(?:r|our)?s?/i);
      const mins = text.match(/(\d+)\s*m(?:in(?:ute)?s?)?\b/i);
      const secs = text.match(/(\d+)\s*s(?:ec(?:ond)?s?)?\b/i);
      if (days) minutes += Number(days[1]) * 1440;
      if (hours) minutes += Number(hours[1]) * 60;
      if (mins) minutes += Number(mins[1]);
      if (secs) minutes += Number(secs[1]) / 60;
      if (minutes > 0) return minutes;
      const hms = text.match(/(\d{1,3}):(\d{2}):(\d{2})/);
      if (hms) {
        return (
          Number(hms[1]) * 60 +
          Number(hms[2]) +
          Number(hms[3]) / 60
        );
      }
      const ms = text.trim().match(/^(\d{1,4}):(\d{2})$/);
      if (ms) {
        return Number(ms[1]) + Number(ms[2]) / 60;
      }
      return 0;
    }
    function formatMinutes(value) {
      const minutes = Math.max(0, Math.round(value));
      if (!minutes) return "0m";
      const hours = Math.floor(minutes / 60);
      const remainder = minutes % 60;
      return hours
        ? `${hours}h ${remainder}m`
        : `${remainder}m`;
    }
    async function fetchApiVitals() {
      const key = String(
        state.settings?.api?.key ||
        context.settings?.api?.key ||
        ""
      ).trim();
      if (!key) return null;
      const requestJson = url => new Promise((resolve, reject) => {
        let request = null;
        if (typeof GM_xmlhttpRequest === "function") {
          request = GM_xmlhttpRequest;
        } else if (
          typeof GM !== "undefined" &&
          typeof GM.xmlHttpRequest === "function"
        ) {
          request = options => GM.xmlHttpRequest(options);
        }
        if (!request) {
          reject(new Error("GM request API unavailable"));
          return;
        }
        request({
          method: "GET",
          url,
          timeout: 20000,
          headers: {
            Accept: "application/json"
          },
          onload: response => {
            if (response.status < 200 || response.status >= 300) {
              reject(new Error(`API HTTP ${response.status}`));
              return;
            }
            try {
              resolve(JSON.parse(response.responseText));
            } catch (error) {
              reject(error);
            }
          },
          onerror: () => reject(new Error("Torn API request failed")),
          ontimeout: () => reject(new Error("Torn API request timed out"))
        });
      });
      try {
        const url = new URL("https://api.torn.com/user/");
        url.searchParams.set("selections", "basic,bars");
        url.searchParams.set("key", key);
        url.searchParams.set(
          "comment",
          "SakaLuX Torn Enhancement Suite Recovery Planner"
        );
        const data = await requestJson(url.toString());
        if (data?.error) {
          throw new Error(
            data.error.error ||
            data.error.message ||
            "Torn API error"
          );
        }
        const currentLife = Number(
          data?.life?.current ??
          data?.bars?.life?.current ??
          0
        );
        const maxLife = Number(
          data?.life?.maximum ??
          data?.life?.max ??
          data?.bars?.life?.maximum ??
          0
        );
        const statusState = String(
          data?.status?.state ||
          data?.status?.description ||
          ""
        ).toLowerCase();
        const statusUntil = Number(
          data?.status?.until ||
          data?.status?.until_timestamp ||
          0
        );
        const nowUnix = Math.floor(Date.now() / 1000);
        const hospitalMins =
          /hospital/.test(statusState) && statusUntil > nowUnix
            ? Math.ceil((statusUntil - nowUnix) / 60)
            : 0;
        if (
          !Number.isFinite(currentLife) ||
          !Number.isFinite(maxLife) ||
          maxLife <= 0
        ) {
          throw new Error("Life data was not returned by Torn API");
        }
        return {
          currentLife,
          maxLife,
          hospitalMins,
          statusState,
          statusUntil
        };
      } catch (error) {
        console.warn(
          "[SakaLuX Suite] Recovery Planner API lookup failed:",
          error
        );
        return null;
      }
    }
    async function fetchHospitalTime() {
      try {
        const response = await fetch("/page.php?sid=UserApiData", {
          credentials: "include",
          headers: {
            "X-Requested-With": "XMLHttpRequest"
          }
        });
        if (!response.ok) return null;
        const data = await response.json();
        const until = Number(data?.hospitalstamp) || 0;
        const now = Math.floor(Date.now() / 1000);
        return until > now
          ? Math.ceil((until - now) / 60)
          : 0;
      } catch {
        return null;
      }
    }
